1	//! Known WASM channels that can be installed from build artifacts.
2	//!
3	//! Instead of embedding WASM binaries in the host binary via include_bytes!,
4	//! channels are compiled separately and installed from their build output
5	//! directories during onboarding.
6	//!
7	//! Channel source layout:
8	//!   channels-src/<name>/
9	//!     target/wasm32-wasip2/release/<name>_channel.wasm
10	//!     <name>.capabilities.json
11	
12	use std::path::{Path, PathBuf};
13	
14	use tokio::fs;
15	
16	/// Compile-time project root, used to locate channels-src/ in dev builds.
17	const CARGO_MANIFEST_DIR: &str = env!("CARGO_MANIFEST_DIR");
18	
19	/// Known channel names and their crate names (for locating build artifacts).
20	const KNOWN_CHANNELS: &[(&str, &str)] = &[
21	    ("darkirc", "darkirc_channel"),
22	    ("discord", "discord_channel"),
23	    ("feishu", "feishu_channel"),
24	    ("slack", "slack_channel"),
25	    ("telegram", "telegram_channel"),
26	    ("weechat", "weechat_relay_channel"),
27	    ("whatsapp", "whatsapp_channel"),
28	    ("xmpp", "xmpp_channel"),
29	];
30	
31	/// Names of known channels that can be installed.
32	pub fn bundled_channel_names() -> Vec<&'static str> {
33	    KNOWN_CHANNELS.iter().map(|(name, _)| *name).collect()
34	}
35	
36	/// Resolve the channels source directory.
37	///
38	/// Checks (in order):
39	/// 1. `IRONCLAW_CHANNELS_SRC` env var
40	/// 2. `<CARGO_MANIFEST_DIR>/channels-src/` (dev builds)
41	fn channels_src_dir() -> PathBuf {
42	    if let Ok(dir) = std::env::var("IRONCLAW_CHANNELS_SRC") {
43	        return PathBuf::from(dir);
44	    }
45	    PathBuf::from(CARGO_MANIFEST_DIR).join("channels-src")
46	}
47	
48	/// Locate the build artifacts for a channel.
49	///
50	/// Checks two layouts:
51	/// 1. **Flat** (Docker/packaged): `<channels_src>/<name>/<name>.wasm`
52	/// 2. **Build tree** (dev): `<channels_src>/<name>/target/wasm32-wasip2/release/<crate_name>.wasm`
53	///
54	/// Returns (wasm_path, capabilities_path) or an error if files are missing.
55	fn locate_channel_artifacts(name: &str) -> Result<(PathBuf, PathBuf), String> {
56	    let (_, crate_name) = KNOWN_CHANNELS
57	        .iter()
58	        .find(|(n, _)| *n == name)
59	        .ok_or_else(|| format!("Unknown channel '{}'", name))?;
60	
61	    let src_dir = channels_src_dir();
62	    let channel_dir = src_dir.join(name);
63	
64	    let caps_path = channel_dir.join(format!("{}.capabilities.json", name));
65	
66	    // Check flat layout first (Docker/packaged deployments)
67	    let flat_wasm = channel_dir.join(format!("{}.wasm", name));
68	    if flat_wasm.exists() && caps_path.exists() {
69	        return Ok((flat_wasm, caps_path));
70	    }
71	
72	    // Fall back to build tree layout (dev builds) — search across all WASM triples
73	    if let Some(build_wasm) =
74	        crate::registry::artifacts::find_wasm_artifact(&channel_dir, crate_name, "release")
75	        && caps_path.exists()
76	    {
77	        return Ok((build_wasm, caps_path));
78	    }
79	
80	    // Provide a helpful error with the paths we checked
81	    let expected_build = crate::registry::artifacts::resolve_target_dir(&channel_dir)
82	        .join("wasm32-wasip2/release")
83	        .join(format!("{}.wasm", crate_name));
84	
85	    Err(format!(
86	        "Channel '{}' WASM not found. Checked:\n  \
87	         - {} (flat/packaged)\n  \
88	         - {} (build tree, and other triples)\n  \
89	         Build it first:\n  \
90	         cd {} && cargo component build --release",
91	        name,
92	        flat_wasm.display(),
93	        expected_build.display(),
94	        channel_dir.display()
95	    ))
96	}
97	
98	/// Install a channel from build artifacts into the channels directory.
99	pub async fn install_bundled_channel(
100	    name: &str,
101	    target_dir: &Path,
102	    force: bool,
103	) -> Result<(), String> {
104	    let (wasm_src, caps_src) = locate_channel_artifacts(name)?;
105	
106	    fs::create_dir_all(target_dir)
107	        .await
108	        .map_err(|e| format!("Failed to create channels directory: {}", e))?;
109	
110	    let wasm_dst = target_dir.join(format!("{}.wasm", name));
111	    let caps_dst = target_dir.join(format!("{}.capabilities.json", name));
112	
113	    let has_existing = wasm_dst.exists() || caps_dst.exists();
114	    if has_existing && !force {
115	        return Err(format!(
116	            "Channel '{}' already exists at {}",
117	            name,
118	            target_dir.display()
119	        ));
120	    }
121	
122	    fs::copy(&wasm_src, &wasm_dst)
123	        .await
124	        .map_err(|e| format!("Failed to copy {}: {}", wasm_src.display(), e))?;
125	    fs::copy(&caps_src, &caps_dst)
126	        .await
127	        .map_err(|e| format!("Failed to copy {}: {}", caps_src.display(), e))?;
128	
129	    Ok(())
130	}
131	
132	/// Check which known channels have build artifacts available.
133	pub fn available_channel_names() -> Vec<&'static str> {
134	    KNOWN_CHANNELS
135	        .iter()
136	        .filter(|(name, _)| locate_channel_artifacts(name).is_ok())
137	        .map(|(name, _)| *name)
138	        .collect()
139	}
