141	#[cfg(test)]
142	mod tests {
143	    use tempfile::tempdir;
144	    use tokio::fs;
145	
146	    use super::*;
147	
148	    #[test]
149	    fn test_known_channels_includes_all() {
150	        let names = bundled_channel_names();
151	        assert!(names.contains(&"darkirc"));
152	        assert!(names.contains(&"discord"));
153	        assert!(names.contains(&"feishu"));
154	        assert!(names.contains(&"slack"));
155	        assert!(names.contains(&"telegram"));
156	        assert!(names.contains(&"weechat"));
157	        assert!(names.contains(&"whatsapp"));
158	        assert!(names.contains(&"xmpp"));
159	    }
160	
161	    #[test]
162	    fn test_channels_src_dir_default() {
163	        let dir = channels_src_dir();
164	        assert!(dir.ends_with("channels-src"));
165	    }
166	
167	    #[test]
168	    fn test_locate_unknown_channel_errors() {
169	        assert!(locate_channel_artifacts("nonexistent").is_err());
170	    }
171	
172	    #[tokio::test]
173	    async fn test_install_refuses_overwrite_without_force() {
174	        let dir = tempdir().unwrap();
175	        let wasm_path = dir.path().join("telegram.wasm");
176	        fs::write(&wasm_path, b"custom").await.unwrap();
177	
178	        let result = install_bundled_channel("telegram", dir.path(), false).await;
179	        // Either fails because artifacts missing OR because file exists
180	        assert!(result.is_err());
181	
182	        // Original file should be untouched
183	        let existing = fs::read(&wasm_path).await.unwrap();
184	        assert_eq!(existing, b"custom");
185	    }
186	}
