319	    /// Load all active WASM tools for a user from storage.
320	    pub async fn load_all_from_storage(
321	        &self,
322	        store: &dyn WasmToolStore,
323	        user_id: &str,
324	    ) -> Result<LoadResults, WasmLoadError> {
325	        let tools = store.list(user_id).await?;
326	        let mut results = LoadResults::default();
327	
328	        for tool in tools {
329	            // Skip non-active tools
330	            if tool.status != crate::tools::wasm::ToolStatus::Active {
331	                continue;
332	            }
333	
334	            match self.load_from_storage(store, user_id, &tool.name).await {
335	                Ok(()) => {
336	                    results.loaded.push(tool.name);
337	                }
338	                Err(e) => {
339	                    tracing::error!(
340	                        name = tool.name,
341	                        user_id = user_id,
342	                        error = %e,
343	                        "Failed to load WASM tool from storage"
344	                    );
345	                    results.errors.push((PathBuf::from(&tool.name), e));
346	                }
347	            }
348	        }
349	
350	        Ok(results)
351	    }
