494	/// Resolve the WASM target directory for a given crate directory.
495	///
496	/// Checks (in order):
497	/// 1. `CARGO_TARGET_DIR` env var (shared target dir)
498	/// 2. `<crate_dir>/target/` (default per-crate layout)
499	pub fn resolve_wasm_target_dir(crate_dir: &Path) -> PathBuf {
500	    crate::registry::artifacts::resolve_target_dir(crate_dir)
501	}
502	
503	/// Return the expected path to a compiled WASM artifact for a given crate.
504	///
505	/// Combines [`resolve_wasm_target_dir`] with the `wasm32-wasip2/release/` subdirectory
506	/// and the binary name without extension (e.g. `slack_tool`).
507	///
508	/// `binary_name` should not include the `.wasm` extension; it is appended automatically.
509	///
510	/// This is a convenience function for callers that know the exact triple (wasip2)
511	/// and binary name. For multi-triple search, use
512	/// [`crate::registry::artifacts::find_wasm_artifact`] instead.
513	pub fn wasm_artifact_path(crate_dir: &Path, binary_name: &str) -> PathBuf {
514	    resolve_wasm_target_dir(crate_dir)
515	        .join("wasm32-wasip2/release")
516	        .join(format!("{}.wasm", binary_name))
517	}
