586	/// Load WASM tools from build artifacts in `tools-src/`.
587	///
588	/// In dev mode, tools can be loaded directly from their build output without
589	/// needing to install them to `~/.ironclaw/tools/` first. Build artifacts
590	/// that are newer than installed copies take priority.
591	///
592	/// Set `IRONCLAW_TOOLS_SRC` env var to override the source directory.
593	pub async fn load_dev_tools(
594	    loader: &WasmToolLoader,
595	    install_dir: &Path,
596	) -> Result<LoadResults, WasmLoadError> {
597	    let dev_tools = discover_dev_tools().await?;
598	    let mut results = LoadResults::default();
599	
600	    if dev_tools.is_empty() {
601	        return Ok(results);
602	    }
603	
604	    for (name, discovered) in &dev_tools {
605	        // Check if the build artifact is newer than the installed copy
606	        let installed_path = install_dir.join(format!("{}.wasm", name));
607	        let should_load = if installed_path.exists() {
608	            // Compare modification times: prefer fresher build artifact
609	            match (
610	                fs::metadata(&discovered.wasm_path).await,
611	                fs::metadata(&installed_path).await,
612	            ) {
613	                (Ok(dev_meta), Ok(inst_meta)) => {
614	                    let dev_modified = dev_meta.modified().unwrap_or(std::time::UNIX_EPOCH);
615	                    let inst_modified = inst_meta.modified().unwrap_or(std::time::UNIX_EPOCH);
616	                    dev_modified > inst_modified
617	                }
618	                _ => true,
619	            }
620	        } else {
621	            true
622	        };
623	
624	        if !should_load {
625	            continue;
626	        }
627	
628	        tracing::info!(
629	            name = name,
630	            wasm_path = %discovered.wasm_path.display(),
631	            "Loading dev tool from build artifacts (newer than installed)"
632	        );
633	
634	        match loader
635	            .load_from_files(
636	                name,
637	                &discovered.wasm_path,
638	                discovered.capabilities_path.as_deref(),
639	            )
640	            .await
641	        {
642	            Ok(()) => {
643	                results.loaded.push(name.clone());
644	            }
645	            Err(e) => {
646	                tracing::error!(
647	                    name = name,
648	                    error = %e,
649	                    "Failed to load dev tool"
650	                );
651	                results.errors.push((discovered.wasm_path.clone(), e));
652	            }
653	        }
654	    }
655	
656	    if !results.loaded.is_empty() {
657	        tracing::info!(
658	            count = results.loaded.len(),
659	            tools = ?results.loaded,
660	            "Loaded dev tools from build artifacts"
661	        );
662	    }
663	
664	    Ok(results)
665	}
