668	///
669	/// Returns a map of tool name -> (wasm_path, capabilities_path).
670	pub async fn discover_tools(dir: &Path) -> Result<HashMap<String, DiscoveredTool>, std::io::Error> {
671	    let mut tools = HashMap::new();
672	
673	    if !dir.is_dir() {
674	        return Ok(tools);
675	    }
676	
677	    let mut entries = fs::read_dir(dir).await?;
678	
679	    while let Some(entry) = entries.next_entry().await? {
680	        let path = entry.path();
681	
682	        if path.extension().and_then(|e| e.to_str()) != Some("wasm") {
683	            continue;
684	        }
685	
686	        let name = match path.file_stem().and_then(|s| s.to_str()) {
687	            Some(n) => n.to_string(),
688	            None => continue,
689	        };
690	
691	        let cap_path = path.with_extension("capabilities.json");
692	
693	        tools.insert(
694	            name,
695	            DiscoveredTool {
696	                wasm_path: path,
697	                capabilities_path: if cap_path.exists() {
698	                    Some(cap_path)
699	                } else {
700	                    None
701	                },
702	            },
703	        );
704	    }
705	
706	    Ok(tools)
707	}
