43	/// PostgreSQL SSL/TLS mode, matching libpq semantics for the common cases.
44	///
45	/// Default is `Prefer`: attempt TLS, fall back to plaintext.  This is the
46	/// safest non-breaking default — local Postgres without TLS keeps working
47	/// while managed providers (Neon, Supabase, RDS) automatically get TLS.
48	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
49	pub enum SslMode {
50	    /// Never use TLS (equivalent to libpq `sslmode=disable`).
51	    Disable,
52	    /// Try TLS first; fall back to plaintext on failure (default).
53	    #[default]
54	    Prefer,
55	    /// Require TLS; fail if the server does not support it.
56	    Require,
57	}
58	
59	impl std::fmt::Display for SslMode {
60	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
61	        match self {
62	            Self::Disable => write!(f, "disable"),
63	            Self::Prefer => write!(f, "prefer"),
64	            Self::Require => write!(f, "require"),
65	        }
66	    }
67	}
68	
69	impl std::str::FromStr for SslMode {
70	    type Err = String;
71	
72	    fn from_str(s: &str) -> Result<Self, Self::Err> {
73	        match s.to_lowercase().as_str() {
74	            "disable" => Ok(Self::Disable),
75	            "prefer" => Ok(Self::Prefer),
76	            "require" => Ok(Self::Require),
77	            _ => Err(format!(
78	                "invalid DATABASE_SSLMODE '{}', expected 'disable', 'prefer', or 'require'",
79	                s
80	            )),
81	        }
82	    }
83	}
