85	/// Database configuration.
86	#[derive(Debug, Clone)]
87	pub struct DatabaseConfig {
88	    /// Which backend to use (default: Postgres).
89	    pub backend: DatabaseBackend,
90	
91	    // -- PostgreSQL fields --
92	    pub url: SecretString,
93	    pub pool_size: usize,
94	    /// TLS mode for PostgreSQL connections (default: Prefer).
95	    pub ssl_mode: SslMode,
96	
97	    // -- libSQL fields --
98	    /// Path to local libSQL database file (default: ~/.ironclaw/ironclaw.db).
99	    pub libsql_path: Option<PathBuf>,
100	    /// Turso cloud URL for remote sync (optional).
101	    pub libsql_url: Option<String>,
102	    /// Turso auth token (required when libsql_url is set).
103	    pub libsql_auth_token: Option<SecretString>,
104	}
105	
106	impl DatabaseConfig {
107	    pub(crate) fn resolve() -> Result<Self, ConfigError> {
108	        let backend: DatabaseBackend = if let Some(b) = optional_env("DATABASE_BACKEND")? {
109	            b.parse().map_err(|e| ConfigError::InvalidValue {
110	                key: "DATABASE_BACKEND".to_string(),
111	                message: e,
112	            })?
113	        } else {
114	            DatabaseBackend::default()
115	        };
116	
117	        // PostgreSQL URL is required only when using the postgres backend.
118	        // For libsql backend, default to an empty placeholder.
119	        // DATABASE_URL is loaded from ~/.ironclaw/.env via dotenvy early in startup.
120	        let url = optional_env("DATABASE_URL")?
121	            .or_else(|| {
122	                if backend == DatabaseBackend::LibSql {
123	                    Some("unused://libsql".to_string())
124	                } else {
125	                    None
126	                }
127	            })
128	            .ok_or_else(|| ConfigError::MissingRequired {
129	                key: "DATABASE_URL".to_string(),
130	                hint: "Run 'ironclaw onboard' or set DATABASE_URL environment variable".to_string(),
131	            })?;
132	
133	        let pool_size = parse_optional_env("DATABASE_POOL_SIZE", 10)?;
134	
135	        let ssl_mode: SslMode = if let Some(s) = optional_env("DATABASE_SSLMODE")? {
136	            s.parse().map_err(|e| ConfigError::InvalidValue {
137	                key: "DATABASE_SSLMODE".to_string(),
138	                message: e,
139	            })?
140	        } else {
141	            SslMode::default()
142	        };
143	
144	        let libsql_path = optional_env("LIBSQL_PATH")?.map(PathBuf::from).or_else(|| {
145	            if backend == DatabaseBackend::LibSql {
146	                Some(default_libsql_path())
147	            } else {
148	                None
149	            }
150	        });
151	
152	        let libsql_url = optional_env("LIBSQL_URL")?;
153	        let libsql_auth_token = optional_env("LIBSQL_AUTH_TOKEN")?.map(SecretString::from);
154	
155	        if libsql_url.is_some() && libsql_auth_token.is_none() {
156	            return Err(ConfigError::MissingRequired {
157	                key: "LIBSQL_AUTH_TOKEN".to_string(),
158	                hint: "LIBSQL_AUTH_TOKEN is required when LIBSQL_URL is set".to_string(),
159	            });
160	        }
161	
162	        Ok(Self {
163	            backend,
164	            url: SecretString::from(url),
165	            pool_size,
166	            ssl_mode,
167	            libsql_path,
168	            libsql_url,
169	            libsql_auth_token,
170	        })
171	    }
172	
173	    /// Create a config from a raw PostgreSQL URL (for wizard/testing).
174	    pub fn from_postgres_url(url: &str, pool_size: usize) -> Self {
175	        Self {
176	            backend: DatabaseBackend::Postgres,
177	            url: SecretString::from(url.to_string()),
178	            pool_size,
179	            ssl_mode: SslMode::from_env(),
180	            libsql_path: None,
181	            libsql_url: None,
182	            libsql_auth_token: None,
183	        }
184	    }
185	
186	    /// Create a config for a libSQL database (for wizard/testing).
187	    ///
188	    /// Empty strings for `turso_url` and `turso_token` are treated as `None`.
189	    pub fn from_libsql_path(
190	        path: &str,
191	        turso_url: Option<&str>,
192	        turso_token: Option<&str>,
193	    ) -> Self {
194	        let turso_url = turso_url.filter(|s| !s.is_empty());
195	        let turso_token = turso_token.filter(|s| !s.is_empty());
196	        Self {
197	            backend: DatabaseBackend::LibSql,
198	            url: SecretString::from("unused://libsql".to_string()),
199	            pool_size: 1,
200	            ssl_mode: SslMode::default(),
201	            libsql_path: Some(PathBuf::from(path)),
202	            libsql_url: turso_url.map(String::from),
203	            libsql_auth_token: turso_token.map(|t| SecretString::from(t.to_string())),
204	        }
205	    }
206	
207	    /// Get the database URL (exposes the secret).
208	    pub fn url(&self) -> &str {
209	        self.url.expose_secret()
210	    }
211	}
