114	    fn env_overrides_settings() {
115	        let _guard = lock_env();
116	        let mut settings = Settings::default();
117	        settings.wasm.default_fuel_limit = 42;
118	
119	        // SAFETY: Under ENV_MUTEX, no concurrent env access.
120	        unsafe { std::env::set_var("WASM_DEFAULT_FUEL_LIMIT", "7") };
121	        let cfg = WasmConfig::resolve(&settings).expect("resolve");
122	        unsafe { std::env::remove_var("WASM_DEFAULT_FUEL_LIMIT") };
123	
124	        assert_eq!(cfg.default_fuel_limit, 7);
125	    }
